import sys

def calculate_self_similarity(s):
    n = len(s)
    z_function = [0] * n
    l, r = 0, 0
    for i in range(1, n):
        if i <= r:
            z_function[i] = min(r - i + 1, z_function[i - l])
        while i + z_function[i] < n and s[z_function[i]] == s[i + z_function[i]]:
            z_function[i] += 1
        if i + z_function[i] - 1 > r:
            l, r = i, i + z_function[i] - 1
    return sum(z_function)

def main():
    import sys
    input = sys.stdin.read().splitlines()
    T = int(input[0])
    results = []
    for i in range(1, T + 1):
        s = input[i]
        result = calculate_self_similarity(s) + len(s)
        results.append(result)
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
